#include <iostream>
#include <cstdio>

using namespace std;

long long gcd(long long a, long long b) {
    while (b != 0) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    long long num1, num2;
    while (scanf("%lld%lld", &num1, &num2) == 2) {
        if (num1 < 0 || num2 < 0) {
            printf("Invalid input\n");
            continue;
        }
        long long gcdValue = gcd(num1, num2);
        long long lcm = (num1 / gcdValue) * num2; // Optimize LCM calculation to avoid overflow
        printf("%lld %lld\n", gcdValue, lcm);
    }
    return 0;
}

