#include <cstdio>
#include <numeric>
using namespace std;

long long gcd(long long a, long long b) {
    while (b != 0) {
        a %= b;
        swap(a, b);
    }
    return a;
}

long long lcm(long long a, long long b) {
    return (a / gcd(a, b)) * b; // safer from overflow
}

int main() {
    long long num1, num2;
    while (scanf("%lld %lld", &num1, &num2) == 2 && num1 >= 0 && num2 >= 0) {
        long long gcdValue = gcd(num1, num2);
        long long lcmValue = lcm(num1, num2); // using the new lcm function
        printf("%lld %lld\n", gcdValue, lcmValue);
    }
    if (num1 < 0 || num2 < 0) {
        printf("Invalid input\n");
    }
    return 0;
}

