#include <numeric>
using namespace std;

long long gcd(long long a, long long b) {
    while (b != 0) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    long long num1, num2;
    while (true) {
        if (!(scanf("%lld%lld", &num1, &num2) == 2)) break;
        if (num1 < 0 || num2 < 0) {
            cout << "Invalid input" << endl;
            continue;
        }
        long long gcdValue = gcd(num1, num2);
        long long lcm = (num1 / gcdValue) * num2; // Prevent overflow
        cout << gcdValue << " " << lcm << endl;
    }
    return 0;
}

